<template>
    <AdminLayout>
        <main class="mx-auto max-w-7xl space-y-6" aria-labelledby="shipping-title">
            <AdminPageHeader eyebrow="CONFIGURACIÓN DE DELIVERY" title="Tarifas de envío" title-id="shipping-title" description="Administra zonas operativas y cobertura de entrega por distrito."><template #action><button type="button" class="min-h-11 rounded-lg bg-blue-700 px-4 font-bold text-white" @click="openZone()">Nueva zona</button></template></AdminPageHeader>

            <section class="rounded-xl bg-white p-4 shadow"><header class="mb-4 flex items-center justify-between"><div><h2 class="text-xl font-black">Zonas de envío</h2><p class="text-sm text-slate-600">Configura la cobertura territorial de delivery.</p></div><button type="button" class="min-h-11 rounded-lg bg-blue-700 px-4 font-bold text-white" @click="openZone()"><i class="pi pi-plus mr-2"></i>Nueva zona</button></header><strong class="block text-2xl">{{ zonePagination.total || 0 }}</strong><span class="text-xs text-slate-500">Total de zonas</span><form class="my-4 grid gap-3 sm:grid-cols-[1fr_12rem_auto]" @submit.prevent="loadZones(1)"><input v-model.trim="filters.search" placeholder="Buscar zona o código" class="min-h-11 rounded-lg border px-3"><select v-model="filters.is_active" class="min-h-11 rounded-lg border px-3"><option value="">Todas</option><option value="1">Activas</option><option value="0">Inactivas</option></select><div class="flex gap-2"><button class="rounded-lg bg-blue-700 px-3 font-bold text-white">Aplicar</button><button type="button" class="rounded-lg border px-3" @click="clearZones">Limpiar</button><button type="button" class="rounded-lg border px-3" title="Actualizar zonas" aria-label="Actualizar zonas" @click="loadZones()"><i class="pi pi-refresh"></i></button></div></form><div v-if="zoneError" class="rounded-lg bg-red-50 p-3 text-red-900">{{ zoneError }} <button type="button" class="font-bold underline" @click="loadZones()">Reintentar</button></div><div v-else-if="loading" class="py-8 text-center text-slate-500">Cargando zonas…</div><div v-else class="overflow-x-auto"><table v-if="zones.length" class="w-full min-w-[680px] text-left text-sm"><thead><tr class="border-b text-slate-500"><th scope="col" class="p-3">Código</th><th scope="col" class="p-3">Zona</th><th scope="col" class="p-3">Plazo</th><th scope="col" class="p-3">Estado</th><th scope="col" class="p-3">Acciones</th></tr></thead><tbody><tr v-for="zone in zones" :key="zone.id" class="border-b"><td class="p-3 font-mono">{{ zone.code }}</td><td class="p-3 font-bold">{{ zone.name }}</td><td class="p-3">{{ zoneDays(zone.estimated_days_min, zone.estimated_days_max) }}</td><td class="p-3"><AdminStatusBadge :active="!!zone.is_active" active-label="Activa" inactive-label="Inactiva" /></td><td class="p-3"><AdminIconButton icon="pi pi-pencil" :label="`Editar ${zone.name}`" @click="openZone(zone)"/><AdminIconButton :icon="zone.is_active ? 'pi pi-ban' : 'pi pi-check-circle'" :label="`${zone.is_active ? 'Desactivar' : 'Activar'} ${zone.name}`" :tone="zone.is_active ? 'text-red-700' : 'text-emerald-700'" @click="toggleZone(zone)"/></td></tr></tbody></table><AdminEmptyState v-else :icon="filters.search || filters.is_active !== '' ? 'pi pi-search' : 'pi pi-map'" :title="filters.search || filters.is_active !== '' ? 'No encontramos zonas con los filtros seleccionados' : 'Todavía no hay zonas de envío'" description="Ajusta los filtros o crea una nueva zona."/></div><AdminPagination :page="zonePagination.current_page || 1" :last-page="zonePagination.last_page || 1" :summary="zonePagination.total ? `Mostrando ${zonePagination.from}–${zonePagination.to} de ${zonePagination.total} zonas` : 'Sin zonas para mostrar'" :loading="loading" @change="loadZones"/></section>

            <section class="rounded-xl bg-white p-4 shadow"><header class="mb-4 flex items-center justify-between gap-3"><div><h2 class="text-xl font-black">Tarifas por distrito</h2><p class="text-sm text-slate-600">Define el importe de delivery por distrito.</p></div><button type="button" class="min-h-11 rounded-lg bg-blue-700 px-4 font-bold text-white" @click="openRate()"><i class="pi pi-plus mr-2"></i>Nueva tarifa</button></header><strong class="block text-2xl">{{ ratePagination.total || 0 }}</strong><span class="text-xs text-slate-500">Total de tarifas</span><form class="my-4 grid gap-3 md:grid-cols-4" @submit.prevent="loadRates(1)"><input v-model.trim="rateFilters.search" placeholder="Zona o distrito" class="min-h-11 rounded-lg border px-3"><select v-model="rateFilters.shipping_zone_id" class="min-h-11 rounded-lg border px-3"><option value="">Todas las zonas</option><option v-for="zone in zones" :key="zone.id" :value="zone.id">{{ zone.name }}</option></select><select v-model="rateFilters.is_active" class="min-h-11 rounded-lg border px-3"><option value="">Todas</option><option value="1">Activas</option><option value="0">Inactivas</option></select><div class="flex gap-2"><button class="rounded-lg bg-blue-700 px-3 font-bold text-white">Aplicar</button><button type="button" class="rounded-lg border px-3" @click="clearRates">Limpiar</button><button type="button" class="rounded-lg border px-3" title="Actualizar tarifas" aria-label="Actualizar tarifas" @click="loadRates()"><i class="pi pi-refresh"></i></button></div></form><div v-if="rateError" class="rounded-lg bg-red-50 p-3 text-red-900">{{ rateError }} <button type="button" class="font-bold underline" @click="loadRates()">Reintentar</button></div><div v-else-if="rateLoading" class="py-8 text-center text-slate-500">Cargando tarifas…</div><div v-else class="overflow-x-auto"><table v-if="rates.length" class="w-full min-w-[900px] text-left text-sm"><thead><tr class="border-b text-slate-500"><th scope="col" class="p-3">Zona</th><th scope="col" class="p-3">Distrito</th><th scope="col" class="p-3">UBIGEO</th><th scope="col" class="p-3">Tarifa</th><th scope="col" class="p-3">Plazo</th><th scope="col" class="p-3">Estado</th><th scope="col" class="p-3">Acciones</th></tr></thead><tbody><tr v-for="rate in rates" :key="rate.id" class="border-b"><td class="p-3">{{ rate.zone?.name || 'Sin zona asignada' }}</td><td class="p-3">{{ rate.district_relation?.name || rate.district || 'Sin distrito configurado' }}</td><td class="p-3 font-mono">{{ rate.district_relation?.ubigeo || rate.ubigeo || '—' }}</td><td class="p-3 font-bold">{{ pen(rate.amount) }}</td><td class="p-3">{{ rateDays(rate.estimated_days_min ?? rate.zone?.estimated_days_min, rate.estimated_days_max ?? rate.zone?.estimated_days_max) }}</td><td class="p-3"><AdminStatusBadge :active="!!rate.is_active" active-label="Activa" inactive-label="Inactiva" /></td><td class="p-3"><AdminIconButton icon="pi pi-pencil" :label="`Editar tarifa de ${rate.district_relation?.name || rate.district || 'distrito'}`" @click="openRate(rate)"/><AdminIconButton :icon="rate.is_active ? 'pi pi-ban' : 'pi pi-check-circle'" :label="`${rate.is_active ? 'Desactivar' : 'Activar'} tarifa`" :tone="rate.is_active ? 'text-red-700' : 'text-emerald-700'" @click="toggleRate(rate)"/></td></tr></tbody></table><AdminEmptyState v-else :icon="rateFilters.search || rateFilters.shipping_zone_id || rateFilters.is_active !== '' ? 'pi pi-search' : 'pi pi-map-marker'" :title="rateFilters.search || rateFilters.shipping_zone_id || rateFilters.is_active !== '' ? 'No encontramos tarifas con los filtros seleccionados' : 'Todavía no hay tarifas registradas'" description="Ajusta los filtros o crea una nueva tarifa."/></div><AdminPagination :page="ratePagination.current_page || 1" :last-page="ratePagination.last_page || 1" :summary="ratePagination.total ? `Mostrando ${ratePagination.from}–${ratePagination.to} de ${ratePagination.total} tarifas` : 'Sin tarifas para mostrar'" :loading="rateLoading" @change="loadRates"/></section>
        </main>

        <div v-if="zoneModal" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/60 p-4" @mousedown.self="zoneModal=false"><form class="w-full max-w-lg space-y-4 rounded-xl bg-white p-6" @submit.prevent="saveZone"><h2 class="text-xl font-black">{{ zoneForm.id ? 'Editar' : 'Nueva' }} zona</h2><label class="block text-sm font-medium">Código<input v-model.trim="zoneForm.code" required maxlength="50" class="mt-1 min-h-11 w-full rounded-lg border px-3"></label><label class="block text-sm font-medium">Nombre<input v-model.trim="zoneForm.name" required class="mt-1 min-h-11 w-full rounded-lg border px-3"></label><label class="block text-sm font-medium">Descripción<textarea v-model.trim="zoneForm.description" class="mt-1 w-full rounded-lg border p-3"></textarea></label><div class="grid grid-cols-2 gap-3"><label class="text-sm font-medium">Días mínimos<input v-model="zoneForm.estimated_days_min" type="number" min="0" class="mt-1 min-h-11 w-full rounded-lg border px-3"></label><label class="text-sm font-medium">Días máximos<input v-model="zoneForm.estimated_days_max" type="number" min="0" class="mt-1 min-h-11 w-full rounded-lg border px-3"></label></div><label class="flex gap-2"><input v-model="zoneForm.is_active" type="checkbox"> Zona activa</label><div class="flex justify-end gap-3"><button type="button" class="min-h-11 px-4" @click="zoneModal=false">Cancelar</button><button class="min-h-11 rounded-lg bg-blue-700 px-4 font-bold text-white">Guardar</button></div></form></div>
        <div v-if="rateModal" class="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-slate-950/60 p-4" @mousedown.self="rateModal=false"><form class="my-6 w-full max-w-xl space-y-4 rounded-xl bg-white p-6" @submit.prevent="saveRate"><h2 class="text-xl font-black">{{ rateForm.id ? 'Editar' : 'Nueva' }} tarifa</h2><label class="block text-sm font-medium">Zona<select v-model="rateForm.shipping_zone_id" required class="mt-1 min-h-11 w-full rounded-lg border px-3"><option disabled value="">Selecciona una zona</option><option v-for="zone in zones" :key="zone.id" :value="zone.id">{{ zone.name }}{{ zone.is_active ? '' : ' (inactiva)' }}</option></select></label><div class="grid gap-3 sm:grid-cols-3"><label class="text-sm font-medium">Departamento<select v-model="rateForm.department_id" required class="mt-1 min-h-11 w-full rounded-lg border px-3" @change="changeRateDepartment"><option :value="null" disabled>Selecciona</option><option v-for="item in departments" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-sm font-medium">Provincia<select v-model="rateForm.province_id" required :disabled="!rateForm.department_id" class="mt-1 min-h-11 w-full rounded-lg border px-3" @change="changeRateProvince"><option :value="null" disabled>Selecciona</option><option v-for="item in provinces" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="text-sm font-medium">Distrito<select v-model="rateForm.district_id" required :disabled="!rateForm.province_id" class="mt-1 min-h-11 w-full rounded-lg border px-3"><option :value="null" disabled>Selecciona</option><option v-for="item in districts" :key="item.id" :value="item.id">{{ item.name }}</option></select></label></div><label class="block text-sm font-medium">Tarifa S/<input v-model.trim="rateForm.amount" required inputmode="decimal" pattern="\d+(\.\d{1,2})?" class="mt-1 min-h-11 w-full rounded-lg border px-3"></label><div class="grid grid-cols-2 gap-3"><label class="text-sm font-medium">Días mínimos<input v-model="rateForm.estimated_days_min" type="number" min="0" class="mt-1 min-h-11 w-full rounded-lg border px-3"></label><label class="text-sm font-medium">Días máximos<input v-model="rateForm.estimated_days_max" type="number" min="0" class="mt-1 min-h-11 w-full rounded-lg border px-3"></label></div><label class="flex gap-2"><input v-model="rateForm.is_active" type="checkbox"> Tarifa activa</label><div class="flex justify-end gap-3"><button type="button" class="min-h-11 px-4" @click="rateModal=false">Cancelar</button><button class="min-h-11 rounded-lg bg-blue-700 px-4 font-bold text-white">Guardar</button></div></form></div>
    </AdminLayout>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue';
import { useToast } from 'primevue/usetoast';
import api from '@/api';
import AdminLayout from '@/layouts/AdminLayout.vue';
import AdminPageHeader from '@/components/admin/AdminPageHeader.vue';
import AdminStatusBadge from '@/components/admin/AdminStatusBadge.vue';
import AdminIconButton from '@/components/admin/AdminIconButton.vue';
import AdminEmptyState from '@/components/admin/AdminEmptyState.vue';
import AdminPagination from '@/components/admin/AdminPagination.vue';

const toast = useToast();
const zones = ref([]), rates = ref([]), loading = ref(false), rateLoading = ref(false), zoneModal = ref(false), rateModal = ref(false);
const zonePagination = ref({ current_page: 1, last_page: 1, total: 0, from: null, to: null }), zoneError = ref('');
const ratePagination = ref({ current_page: 1, last_page: 1, total: 0, from: null, to: null }), rateError = ref('');
const departments = ref([]), provinces = ref([]), districts = ref([]);
const filters = reactive({ search: '', is_active: '' });
const rateFilters = reactive({ search: '', shipping_zone_id: '', is_active: '' });
const emptyZone = () => ({ id: null, code: '', name: '', description: '', estimated_days_min: '', estimated_days_max: '', is_active: true });
const emptyRate = () => ({ id: null, shipping_zone_id: '', department_id: null, province_id: null, district_id: null, amount: '', estimated_days_min: '', estimated_days_max: '', is_active: true });
const zoneForm = reactive(emptyZone()), rateForm = reactive(emptyRate());
const clean = data => Object.fromEntries(Object.entries(data).map(([key, value]) => [key, value === '' ? null : value]));
const money = value => Number(value || 0).toFixed(2);
const pen = value => Number.isFinite(Number(value)) ? `S/ ${Number(value).toFixed(2)}` : 'S/ 0.00';
const days = (min, max) => min == null && max == null ? 'Por confirmar' : min === max ? `${min} día(s)` : `${min ?? 0}–${max ?? min} días`;
const zoneDays = (min, max) => min == null && max == null ? 'Sin plazo configurado' : min === max ? `${min} día` : `${min}–${max} días`;
const rateDays = zoneDays;
const fail = error => toast.add({ severity: 'error', summary: 'No se pudo guardar', detail: Object.values(error.response?.data?.errors || {})[0]?.[0] || error.response?.data?.message || error.message, life: 5000 });
async function loadZones(page = zonePagination.value.current_page || 1) { if (loading.value) return; loading.value = true; zoneError.value = ''; try { const response = await api.get('/admin/shipping-zones', { params: { page, search: filters.search || undefined, is_active: filters.is_active === '' ? undefined : filters.is_active } }); zones.value = response.data.data || []; zonePagination.value = response.data; } catch (error) { zoneError.value = error.response?.data?.message || error.message; } finally { loading.value = false; } }
function clearZones() { filters.search = ''; filters.is_active = ''; loadZones(1); }
async function loadRates(page = ratePagination.value.current_page || 1) { if (rateLoading.value) return; rateLoading.value = true; rateError.value = ''; try { const response = await api.get('/admin/shipping-rates', { params: { page, search: rateFilters.search || undefined, shipping_zone_id: rateFilters.shipping_zone_id || undefined, is_active: rateFilters.is_active === '' ? undefined : rateFilters.is_active } }); rates.value = response.data.data || []; ratePagination.value = response.data; } catch (error) { rateError.value = error.response?.data?.message || error.message; } finally { rateLoading.value = false; } }
function clearRates() { rateFilters.search = ''; rateFilters.shipping_zone_id = ''; rateFilters.is_active = ''; loadRates(1); }
function openZone(zone = null) { Object.assign(zoneForm, emptyZone(), zone || {}); zoneModal.value = true; }
async function openRate(rate = null) { Object.assign(rateForm, emptyRate(), rate || {}); if (rate?.district_relation?.province) { rateForm.department_id = rate.district_relation.province.department_id; rateForm.province_id = rate.district_relation.province_id; } provinces.value = rateForm.department_id ? (await api.get('/location/provinces', { params: { department_id: rateForm.department_id } })).data : []; districts.value = rateForm.province_id ? (await api.get('/location/districts', { params: { province_id: rateForm.province_id } })).data : []; rateModal.value = true; }
async function changeRateDepartment() { rateForm.province_id = null; rateForm.district_id = null; districts.value = []; provinces.value = rateForm.department_id ? (await api.get('/location/provinces', { params: { department_id: rateForm.department_id } })).data : []; }
async function changeRateProvince() { rateForm.district_id = null; districts.value = rateForm.province_id ? (await api.get('/location/districts', { params: { province_id: rateForm.province_id } })).data : []; }
async function saveZone() { try { const payload = clean({ ...zoneForm }); delete payload.id; zoneForm.id ? await api.put(`/admin/shipping-zones/${zoneForm.id}`, payload) : await api.post('/admin/shipping-zones', payload); zoneModal.value = false; await Promise.all([loadZones(), loadRates()]); } catch (error) { fail(error); } }
async function saveRate() { try { const payload = clean({ ...rateForm }); delete payload.id; rateForm.id ? await api.put(`/admin/shipping-rates/${rateForm.id}`, payload) : await api.post('/admin/shipping-rates', payload); rateModal.value = false; await Promise.all([loadZones(), loadRates()]); } catch (error) { fail(error); } }
async function toggleZone(zone) { if (!confirm(`¿${zone.is_active ? 'Desactivar' : 'Activar'} la zona ${zone.name}?`)) return; try { await api.patch(`/admin/shipping-zones/${zone.id}/status`, { is_active: !zone.is_active }); await Promise.all([loadZones(), loadRates()]); } catch (error) { fail(error); } }
async function toggleRate(rate) { if (!confirm(`¿${rate.is_active ? 'Desactivar' : 'Activar'} la tarifa de ${rate.district}?`)) return; try { await api.patch(`/admin/shipping-rates/${rate.id}/status`, { is_active: !rate.is_active }); await Promise.all([loadZones(), loadRates()]); } catch (error) { fail(error); } }
onMounted(async () => { departments.value = (await api.get('/location/departments')).data; await Promise.all([loadZones(), loadRates()]); });
</script>
